import os
itens=[]
for raiz,_,arqs in os.walk('.'):
    for a in arqs:
        p=os.path.join(raiz,a)
        try: itens.append((os.path.getsize(p),p))
        except OSError: pass
itens.sort(reverse=True)
for t,p in itens[:10]: print(f'{t/1024:10.1f} KB  {p}')
print(f'{len(itens)} arquivos no total') if itens else print('pasta vazia')
